<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role('cashier');
$title='Kendaraan';
if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO vehicles(customer_id,plate_number,vehicle_type,brand,color)VALUES(?,?,?,?,?)")->execute([(int)$_POST['customer_id'],trim($_POST['plate_number']),$_POST['vehicle_type'],trim($_POST['brand']),trim($_POST['color'])]);header('Location:/cashier/vehicles.php');exit;}
$customers=$pdo->query("SELECT * FROM customers ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT v.*,c.name customer FROM vehicles v JOIN customers c ON c.id=v.customer_id ORDER BY v.id DESC")->fetchAll();require __DIR__.'/../includes/header.php';?><h2>Kendaraan</h2><div class="card mb-3"><div class="card-body"><form method="post" class="row g-2"><div class="col-md-3"><select class="form-select" name="customer_id" required><option value="">Pelanggan</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" name="plate_number" placeholder="Plat" required></div><div class="col-md-2"><select class="form-select" name="vehicle_type"><option>Mobil</option><option>Motor</option></select></div><div class="col-md-2"><input class="form-control" name="brand" placeholder="Merek"></div><div class="col-md-2"><input class="form-control" name="color" placeholder="Warna"></div><div class="col-md-1"><button class="btn btn-dark">Tambah</button></div></form></div></div><div class="card"><div class="card-body"><table class="table"><tr><th>Pelanggan</th><th>Plat</th><th>Jenis</th><th>Merek</th><th>Warna</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['customer'])?></td><td><?=e($r['plate_number'])?></td><td><?=$r['vehicle_type']?></td><td><?=e($r['brand'])?></td><td><?=e($r['color'])?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
